const READ_NODE_NAMES = [
  'Read Operative Job Sheet photos',
  'Read Operative Job Sheet1',
  'Read Operative Job Sheet',
];

const READY_COL = 'Ready To Hand over';
const HANDOVER_PHOTOS_COL = 'Hand Over Photos Extracted';

function sheetRowsFromNode(nodeName) {
  try {
    return $(nodeName).all().map((i) => i.json || {});
  } catch (e) {
    return [];
  }
}

function rowDedupeKey(row) {
  const id = String(row.smart_form_x_id ?? row['smart_form_x_id'] ?? '').trim();
  if (id) return `id::${id}`;
  const rn = String(row.row_number ?? row.rowNumber ?? '').trim();
  if (rn) return `row::${rn}`;
  return null;
}

function collectAllSheetRows() {
  const merged = new Map();
  let seq = 0;
  function addRow(row) {
    if (!row || typeof row !== 'object') return;
    const key = rowDedupeKey(row) || `seq::${seq++}`;
    merged.set(key, row);
  }
  for (const item of $input.all()) addRow(item.json || {});
  for (const nodeName of READ_NODE_NAMES) {
    for (const row of sheetRowsFromNode(nodeName)) addRow(row);
  }
  return [...merged.values()];
}

function isHeaderRow(row) {
  return /^smartform name$/i.test(String(row['SmartForm Name'] ?? row.smart_form_name ?? '').trim());
}

function normKey(name, dateCreated) {
  return `${String(name || '').trim().toLowerCase().replace(/\s+/g, ' ')}::${String(dateCreated || '').trim()}`;
}

function isBccResponseRepairsName(name) {
  return /:\s*BCC\s+Respon(?:se|sive)\s+Repairs\b/i.test(String(name || '').trim());
}

function cellVal(row, exactNames, containsText) {
  for (const name of exactNames) {
    if (row[name] !== undefined && row[name] !== null) {
      const v = String(row[name]).trim();
      if (v) return v;
    }
  }
  if (containsText) {
    const needle = String(containsText).toLowerCase();
    for (const k of Object.keys(row || {})) {
      if (k.toLowerCase().includes(needle)) {
        const v = String(row[k] ?? '').trim();
        if (v) return v;
      }
    }
  }
  return '';
}

function isYes(v) {
  const s = String(v ?? '').trim().toLowerCase();
  return s === 'yes' || s === 'y' || s === 'true' || s === '1';
}

function isReadyToHandover(row) {
  return isYes(cellVal(row, [READY_COL, 'Ready To Hand Over'], 'ready to hand'));
}

function isHandOverPhotosExtracted(row) {
  const v = cellVal(row, [HANDOVER_PHOTOS_COL, 'Hand over photos extracted'], 'hand over photos extracted');
  if (!v) return false;
  const s = v.toLowerCase();
  if (s === 'no' || s === 'false' || s === '0' || s === 'n') return false;
  return true;
}

const rows = collectAllSheetRows();
const skip_smart_form_ids = [];
const skip_entries = [];
const force_extract_smart_form_ids = [];
const id_row_number = {};
const seenIds = new Set();
const seenKeys = new Set();
const PHOTO_BACKFILL_LIMIT = 8;
let dataRowCount = 0;
let skipped_not_ready_handover = 0;
let skipped_handover_photos_done = 0;

for (const row of rows) {
  if (isHeaderRow(row)) continue;
  dataRowCount++;

  const id = String(row.smart_form_x_id ?? row['smart_form_x_id'] ?? '').trim();
  if (id) {
    if (!seenIds.has(id)) {
      seenIds.add(id);
      skip_smart_form_ids.push(id);
    }
    const rn = row.row_number ?? row.rowNumber;
    if (rn !== null && rn !== undefined && rn !== '') id_row_number[id] = rn;
  }

  const name = row['SmartForm Name'] ?? row.smart_form_name ?? row.form_name ?? '';
  const dateCreated = row['Date Created'] ?? row.date_created ?? '';
  if (name && dateCreated) {
    const key = normKey(name, dateCreated);
    if (!seenKeys.has(key)) {
      seenKeys.add(key);
      skip_entries.push({
        smart_form_name: String(name).trim(),
        date_created: String(dateCreated).trim(),
      });
    }
  }

  if (!id || !isBccResponseRepairsName(name)) continue;

  if (!isReadyToHandover(row)) {
    skipped_not_ready_handover++;
    continue;
  }

  if (isHandOverPhotosExtracted(row)) {
    skipped_handover_photos_done++;
    continue;
  }

  if (force_extract_smart_form_ids.length < PHOTO_BACKFILL_LIMIT) {
    force_extract_smart_form_ids.push(id);
  }
}

return [{
  json: {
    skip_smart_form_ids,
    skip_entries,
    force_extract_smart_form_ids,
    id_row_number,
    photo_backfill_count: force_extract_smart_form_ids.length,
    skipped_not_ready_handover,
    skipped_handover_photos_done,
    sheet_row_count: dataRowCount,
  },
}];

function extractApiBody(resp) {
  const statusCode = resp.statusCode ?? resp.status ?? 0;
  let body = resp.body ?? resp.data ?? resp;
  if (typeof body === 'string') {
    try {
      body = JSON.parse(body);
    } catch (e) {
      const m = body.match(/\{[\s\S]*\}/);
      if (m) {
        try { body = JSON.parse(m[0]); } catch (e2) { body = {}; }
      } else {
        body = {};
      }
    }
  }
  if (
    body &&
    typeof body === 'object' &&
    body.body &&
    body.results === undefined &&
    body.total_extracted === undefined
  ) {
    body = body.body;
  }
  return { statusCode, body: body || {} };
}

const skipPayload = $('Build photo backfill queue').first().json || {};
const forceSet = new Set((skipPayload.force_extract_smart_form_ids || []).map((x) => String(x).trim()).filter(Boolean));
const idRowNumber = skipPayload.id_row_number || {};

const respRaw = $('POST extract for photos').first().json || {};
const { statusCode, body } = extractApiBody(respRaw);
const results = Array.isArray(body.results) ? body.results : [];

const out = [];
for (const r of results) {
  const sfid = String(r.smart_form_x_id || '').trim();
  if (!forceSet.has(sfid)) continue;

  const parsed = r.parsed || {};
  const grid = r.grid || {};
  const cells = grid.cells || {};
  const smartFormName =
    grid.form_name || cells.list_form_name || parsed.job_header || '';

  const photos = parsed.photos || {};
  const completed = Array.isArray(photos.completed_work) ? photos.completed_work : [];
  const variations = Array.isArray(photos.variations) ? photos.variations : [];
  if (!completed.length && !variations.length) continue;

  out.push({
    json: {
      _skip_append: true,
      _photo_backfill: true,
      row_number: idRowNumber[sfid],
      smart_form_x_id: sfid,
      'SmartForm Name': String(smartFormName).trim(),
      _photos: photos,
      pdf_url: r.pdf_url || '',
    },
  });
}

if (!out.length) {
  return [
    {
      json: {
        _skip_append: true,
        _workflow_only: true,
        message:
          forceSet.size === 0
            ? 'No handover-ready rows queued (Ready To Hand over=Yes and Hand Over Photos Extracted empty).'
            : `No photos found in PDF for ${forceSet.size} handover target(s).`,
        photo_backfill_count: forceSet.size,
        photo_rows_with_images: 0,
        skipped_not_ready_handover: skipPayload.skipped_not_ready_handover ?? 0,
        skipped_handover_photos_done: skipPayload.skipped_handover_photos_done ?? 0,
        api_status: statusCode,
        total_extracted: body.total_extracted ?? 0,
        total_errors: body.total_errors ?? 0,
      },
    },
  ];
}

return out;

const resp = $('Get OJS photos root folder').first().json || {};
const statusCode = resp.statusCode ?? resp.status ?? 0;
let body = resp.body ?? resp.data ?? resp;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch {} }
if (body && body.body && !body.id) body = body.body;
const root = body || {};
return [{ json: { exists: Boolean(root.id), root_id: root.id || '', status_code: statusCode, drive_id: $('Get BCC library drive OJS').first().json.id } }];

function sharePointFolderName(name) {
  return String(name || '')
    .trim()
    .replace(/[:*?"<>|/\\]/g, ' - ')
    .replace(/\s+/g, ' ')
    .replace(/(?:\s-\s)+/g, ' - ')
    .trim()
    .slice(0, 200);
}

function photoFilename(photo) {
  return String((photo && photo.filename) || '').trim().toLowerCase();
}

function pipelineRows() {
  return $('Format photo extract results').all()
    .map((i) => i.json || {})
    .filter((row) => {
      if (row._skip_append === true && !row._photo_backfill) return false;
      const photos = row._photos || {};
      const c = Array.isArray(photos.completed_work) ? photos.completed_work.length : 0;
      const v = Array.isArray(photos.variations) ? photos.variations.length : 0;
      return c + v > 0;
    });
}

const rows = pipelineRows();
const root = $('Parse OJS root folder').first().json || {};
let listResp = {};
try { listResp = $('List OJS job folders').first().json || {}; } catch (e) { listResp = {}; }
const children = Array.isArray(listResp.value) ? listResp.value : [];
const byName = new Map(
  children
    .filter((c) => c && c.folder)
    .map((c) => [String(c.name || '').trim(), { id: String(c.id || '').trim(), webUrl: String(c.webUrl || '').trim() }]),
);

const bySite = new Map();
for (const row of rows) {
  const photos = row._photos || {};
  const folderName = String(photos.smart_form_name || row['SmartForm Name'] || '').trim();
  const spFolderName = sharePointFolderName(folderName);
  if (!folderName || !spFolderName) continue;

  if (!bySite.has(spFolderName)) {
    const hit = byName.get(spFolderName) || {};
    bySite.set(spFolderName, {
      smart_form_x_id: String(row.smart_form_x_id || '').trim(),
      folder_name: folderName,
      sharepoint_folder_name: spFolderName,
      completed_work: [],
      variations: [],
      seen_files: new Set(),
      visit_rows: [],
      drive_id: root.drive_id || '',
      root_folder_id: root.root_id || '',
      folder_item_id: hit.id || '',
      folder_web_url: hit.webUrl || '',
    });
  }

  const site = bySite.get(spFolderName);
  site.visit_rows.push({
    smart_form_x_id: String(row.smart_form_x_id || '').trim(),
    row_number: row.row_number,
    _photo_backfill: row._photo_backfill === true,
  });

  const pushPhotos = (list, bucket) => {
    for (const photo of list || []) {
      const fn = photoFilename(photo);
      if (!fn || site.seen_files.has(fn)) continue;
      site.seen_files.add(fn);
      site[bucket].push(photo);
    }
  };
  pushPhotos(photos.completed_work, 'completed_work');
  pushPhotos(photos.variations, 'variations');
}

const out = [];
for (const site of bySite.values()) {
  delete site.seen_files;
  if (!site.completed_work.length && !site.variations.length) continue;
  out.push({ json: site });
}

if (!out.length) return [{ json: { skip_photo_upload: true } }];
return out;

function sharePointFolderName(name) {
  return String(name || '')
    .trim()
    .replace(/[:*?"<>|/\\]/g, ' - ')
    .replace(/\s+/g, ' ')
    .replace(/(?:\s-\s)+/g, ' - ')
    .trim()
    .slice(0, 200);
}

function safeNodeAll(nodeName) {
  try {
    return $(nodeName).all().map((item) => item.json || {});
  } catch (error) {
    return [];
  }
}

const prepared = $('Plan site photo folders').all().map((item) => item.json || {});
const folderMeta = new Map();

for (const item of prepared) {
  const key = item.sharepoint_folder_name || sharePointFolderName(item.folder_name);
  if (!key) continue;
  folderMeta.set(key, {
    id: item.folder_item_id || folderMeta.get(key)?.id || '',
    webUrl: item.folder_web_url || folderMeta.get(key)?.webUrl || '',
  });
}

for (const item of $input.all().map((entry) => entry.json || {})) {
  const key = item.sharepoint_folder_name || sharePointFolderName(item.folder_name || item.name);
  const id = String(item.folder_item_id || item.id || '').trim();
  const webUrl = String(item.folder_web_url || item.webUrl || '').trim();
  if (!key) continue;
  const prev = folderMeta.get(key) || { id: '', webUrl: '' };
  folderMeta.set(key, {
    id: id || prev.id,
    webUrl: webUrl || prev.webUrl,
  });
}

for (const item of safeNodeAll('Create OJS job folder')) {
  const key = sharePointFolderName(item.name);
  const id = String(item.id || '').trim();
  const webUrl = String(item.webUrl || '').trim();
  if (!key) continue;
  folderMeta.set(key, { id: id || folderMeta.get(key)?.id || '', webUrl: webUrl || folderMeta.get(key)?.webUrl || '' });
}

const uploads = [];
for (const row of prepared) {
  const key = row.sharepoint_folder_name || sharePointFolderName(row.folder_name);
  const meta = folderMeta.get(key) || {};
  const folderId = meta.id || row.folder_item_id || '';
  const folderWebUrl = meta.webUrl || row.folder_web_url || '';
  if (!folderId) continue;

  const pushPhoto = (photo, kind) => {
    const fileName = String(photo.filename || 'photo.jpg').trim();
    uploads.push({
      smart_form_x_id: row.smart_form_x_id,
      folder_name: row.folder_name,
      sharepoint_folder_name: key,
      folder_item_id: folderId,
      folder_web_url: folderWebUrl,
      file_name: fileName,
      upload_url: `https://graph.microsoft.com/v1.0/drives/${row.drive_id}/items/${folderId}:/${encodeURIComponent(fileName)}:/content`,
      photo_kind: kind,
      mime_type: photo.mime_type || 'image/jpeg',
      content_base64: photo.content_base64,
      drive_id: row.drive_id,
    });
  };

  for (const photo of row.completed_work || []) pushPhoto(photo, 'completed_work');
  for (const photo of row.variations || []) pushPhoto(photo, 'variations');
}

if (!uploads.length) {
  return [{ json: { skip_photo_upload: true } }];
}

return uploads.map((item) => ({ json: item }));

const base64Data = String($json.content_base64 || '').trim();
const fileName = String($json.file_name || 'photo.jpg').trim();
const mimeType = $json.mime_type || 'image/jpeg';
const uploadUrl = String($json.upload_url || '').trim();
if (!base64Data) throw new Error(`No photo data for ${fileName}`);
if (!uploadUrl) throw new Error(`Missing upload_url for ${fileName}`);
const buffer = Buffer.from(base64Data, 'base64');
const binary = await this.helpers.prepareBinaryData(buffer, fileName, mimeType);
return { json: { ...$json, photo_bytes: buffer.length, upload_url: uploadUrl }, binary: { attachment_0: binary } };

const Q23_COL = 'Q2.3 Please provide photos of completed work';
const Q26_COL = 'Q2.6 Please provide photos of variations ( if Variation was yes)';
const ALT_Q26_COL = 'Q2.6 Please provide photos of variations';

function pickQ26Col(row) {
  if (Object.prototype.hasOwnProperty.call(row, Q26_COL)) return Q26_COL;
  if (Object.prototype.hasOwnProperty.call(row, ALT_Q26_COL)) return ALT_Q26_COL;
  return Q26_COL;
}

function sharePointFolderName(name) {
  return String(name || '')
    .trim()
    .replace(/[:*?"<>|/\\]/g, ' - ')
    .replace(/\s+/g, ' ')
    .replace(/(?:\s-\s)+/g, ' - ')
    .trim()
    .slice(0, 200);
}

function safeNodeAll(nodeName) {
  try {
    return $(nodeName).all().map((item) => item.json || {});
  } catch (e) {
    return [];
  }
}

function safeNodeFirst(nodeName) {
  try {
    return $(nodeName).first()?.json || {};
  } catch (e) {
    return {};
  }
}

function pipelineRows() {
  return $('Format photo extract results').all()
    .map((item) => item.json || {})
    .filter((row) => row._photo_backfill === true && row.row_number);
}

const folderUrlBySite = new Map();

const listResp = safeNodeFirst('List OJS job folders');
for (const c of Array.isArray(listResp.value) ? listResp.value : []) {
  if (c && c.folder) {
    const name = String(c.name || '').trim();
    const url = String(c.webUrl || '').trim();
    if (name && url) folderUrlBySite.set(name, url);
  }
}

for (const src of safeNodeAll('Plan site photo folders')) {
  const key = String(src.sharepoint_folder_name || sharePointFolderName(src.folder_name || '')).trim();
  const url = String(src.folder_web_url || '').trim();
  if (key && url) folderUrlBySite.set(key, url);
}

for (const src of safeNodeAll('Create OJS job folder')) {
  const key = sharePointFolderName(src.name);
  const url = String(src.webUrl || '').trim();
  if (key && url) folderUrlBySite.set(key, url);
}

for (const src of safeNodeAll('Convert OJS photo to binary')) {
  const key = String(src.sharepoint_folder_name || sharePointFolderName(src.folder_name || '')).trim();
  const url = String(src.folder_web_url || '').trim();
  if (key && url) folderUrlBySite.set(key, url);
}

for (const item of $input.all()) {
  const src = item.json || {};
  const key = String(src.sharepoint_folder_name || sharePointFolderName(src.folder_name || src.name || '')).trim();
  const url = String(src.folder_web_url || src.webUrl || '').trim();
  if (key && url) folderUrlBySite.set(key, url);
}

const out = [];
for (const row of pipelineRows()) {
  const photos = row._photos || {};
  const smartFormName = String(photos.smart_form_name || row['SmartForm Name'] || '').trim();
  const nameKey = sharePointFolderName(smartFormName);
  const folderUrl = folderUrlBySite.get(nameKey) || '';
  if (!folderUrl) continue;

  const hasCompleted = Array.isArray(photos.completed_work) && photos.completed_work.length > 0;
  const hasVariations = Array.isArray(photos.variations) && photos.variations.length > 0;
  const q26Col = pickQ26Col(row);
  const update = {
    row_number: row.row_number,
  };
  if (hasCompleted) update[Q23_COL] = folderUrl;
  if (hasVariations) update[q26Col] = folderUrl;
  if (hasCompleted || hasVariations) update['Hand Over Photos Extracted'] = 'Yes';
  out.push({ json: update });
}

if (!out.length) {
  return [];
}

return out;

function safeFirst(nodeName) {
  try {
    return $(nodeName).first()?.json || {};
  } catch (e) {
    return {};
  }
}

function formatMeta() {
  try {
    const items = $('Format photo extract results').all().map((i) => i.json || {});
    return items.find((j) => j._workflow_only === true) || items[0] || {};
  } catch (e) {
    return {};
  }
}

const queue = safeFirst('Build photo backfill queue');
const formatFirst = formatMeta();
const updated = (() => {
  try {
    return $('Update photo URLs on sheet').all().length;
  } catch (e) {
    return 0;
  }
})();

const queued = queue.photo_backfill_count ?? formatFirst.photo_backfill_count ?? 0;
const withPhotos = (() => {
  try {
    return $('Format photo extract results').all().filter((i) => (i.json || {})._photo_backfill === true).length;
  } catch (e) {
    return 0;
  }
})();
const skippedDone = queue.skipped_handover_photos_done ?? formatFirst.skipped_handover_photos_done ?? 0;
const skippedNotReady = queue.skipped_not_ready_handover ?? formatFirst.skipped_not_ready_handover ?? 0;

let message = formatFirst.message || '';
if (!message) {
  if (queued === 0) {
    message = 'No handover-ready rows queued.';
  } else if (withPhotos > 0) {
    message = `Processed ${withPhotos} handover row(s) with photos.`;
  } else {
    message = `Queued ${queued} row(s) but no photos extracted.`;
  }
}
if (skippedDone > 0) message += ` Skipped ${skippedDone} already extracted.`;
if (skippedNotReady > 0) message += ` Skipped ${skippedNotReady} not ready to hand over.`;
if (updated > 0) message += ` Updated ${updated} sheet row(s).`;

return [{
  json: {
    ok: withPhotos > 0 || updated > 0,
    message,
    photo_backfill_count: queued,
    photo_rows_with_images: withPhotos,
    skipped_handover_photos_done: skippedDone,
    skipped_not_ready_handover: skippedNotReady,
    sheet_rows_updated: updated,
    api_status: formatFirst.api_status ?? null,
    total_extracted: formatFirst.total_extracted ?? null,
    total_errors: formatFirst.total_errors ?? null,
  },
}];

const Q23_COL = 'Q2.3 Please provide photos of completed work';
const Q26_COL = 'Q2.6 Please provide photos of variations ( if Variation was yes)';
const ALT_Q26_COL = 'Q2.6 Please provide photos of variations';

const ALLOWED = new Set([
  'row_number',
  Q23_COL,
  Q26_COL,
  ALT_Q26_COL,
  'Hand Over Photos Extracted',
]);

function pickQ26Col(row) {
  if (Object.prototype.hasOwnProperty.call(row, Q26_COL)) return Q26_COL;
  if (Object.prototype.hasOwnProperty.call(row, ALT_Q26_COL)) return ALT_Q26_COL;
  return Q26_COL;
}

const out = [];
for (const item of $input.all()) {
  const row = item.json || {};
  if (!row.row_number) continue;
  const clean = { row_number: row.row_number };
  if (row[Q23_COL]) clean[Q23_COL] = row[Q23_COL];
  const q26 = pickQ26Col(row);
  if (row[q26]) clean[q26] = row[q26];
  if (row['Hand Over Photos Extracted']) clean['Hand Over Photos Extracted'] = row['Hand Over Photos Extracted'];
  const hasUpdate = Object.keys(clean).length > 1;
  if (hasUpdate) out.push({ json: clean });
}

return out;
